begin;
create table if not exists public.admin_users (user_id uuid primary key references auth.users(id) on delete cascade, email text not null unique, created_at timestamptz not null default now());
alter table public.admin_users enable row level security;
alter table public.admin_users force row level security;
revoke all on public.admin_users from anon, authenticated;
revoke all on public.admin_users from public;
create or replace function public.is_admin() returns boolean language sql security definer stable set search_path = pg_catalog, public as $$ select exists (select 1 from public.admin_users where user_id = (select auth.uid())) $$;
revoke all on function public.is_admin() from public;
grant execute on function public.is_admin() to authenticated;
do $$ begin if not exists (select 1 from auth.users where lower(email)='bimaaryadinata01@gmail.com') then raise exception 'Bootstrap admin account does not exist'; end if; end $$;
insert into public.admin_users (user_id,email) select id,email from auth.users where lower(email)='bimaaryadinata01@gmail.com' on conflict (user_id) do update set email=excluded.email;
do $$ declare t text; p record; begin foreach t in array array['projects','skills','experiences','education','profile'] loop if to_regclass('public.'||t) is null then raise exception 'Required table missing: %', t; end if; for p in select policyname from pg_policies where schemaname='public' and tablename=t loop execute format('drop policy if exists %I on public.%I',p.policyname,t); end loop; execute format('create policy %I on public.%I for select to anon, authenticated using (true)',t||'_public_select',t); execute format('create policy %I on public.%I for insert to authenticated with check (public.is_admin())',t||'_admin_insert',t); execute format('create policy %I on public.%I for update to authenticated using (public.is_admin()) with check (public.is_admin())',t||'_admin_update',t); execute format('create policy %I on public.%I for delete to authenticated using (public.is_admin())',t||'_admin_delete',t); end loop; end $$;
create table if not exists public.contact_messages (id bigint generated by default as identity primary key,name text not null,email text not null,message text not null,locale text not null default 'en',created_at timestamptz not null default now());
alter table public.contact_messages enable row level security;
drop policy if exists contact_messages_public_insert on public.contact_messages;
revoke all on public.contact_messages from anon, authenticated;
revoke all on public.contact_messages from public;
do $$ declare p record; begin if to_regclass('public.analytics_events') is not null then for p in select policyname from pg_policies where schemaname='public' and tablename='analytics_events' and cmd='SELECT' loop execute format('drop policy if exists %I on public.analytics_events',p.policyname); end loop; execute 'create policy analytics_admin_select on public.analytics_events for select to authenticated using (public.is_admin())'; end if; end $$;
do $$ declare p record; begin for p in select policyname, cmd from pg_policies where schemaname='storage' and tablename='objects' and cmd in ('INSERT','UPDATE','DELETE') and policyname not in ('Auth upload portfolio-assets','Auth update portfolio-assets','Auth delete portfolio-assets') loop raise exception 'Unexpected storage write policy: % (%)', p.policyname, p.cmd; end loop; end $$;
drop policy if exists "Public read portfolio-assets" on storage.objects;
drop policy if exists "Auth upload portfolio-assets" on storage.objects;
drop policy if exists "Auth update portfolio-assets" on storage.objects;
drop policy if exists "Auth delete portfolio-assets" on storage.objects;
create policy "Public read portfolio-assets" on storage.objects for select using (bucket_id = 'portfolio-assets');
create policy "Auth upload portfolio-assets" on storage.objects for insert to authenticated with check (bucket_id = 'portfolio-assets' and public.is_admin());
create policy "Auth update portfolio-assets" on storage.objects for update to authenticated using (bucket_id = 'portfolio-assets' and public.is_admin()) with check (bucket_id = 'portfolio-assets' and public.is_admin());
create policy "Auth delete portfolio-assets" on storage.objects for delete to authenticated using (bucket_id = 'portfolio-assets' and public.is_admin());
create or replace function public.project_media_append(p_id bigint, p_url text) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ begin if not public.is_admin() or p_id < 1 or p_url !~ ('^https?://[^/]+/storage/v1/object/public/portfolio-assets/projects/' || p_id::text || '/[^/]+$') then raise exception 'Invalid media request'; end if; update public.projects set images = case when images @> jsonb_build_array(p_url) then images else coalesce(images,'[]'::jsonb) || jsonb_build_array(p_url) end where id=p_id; if not found then raise exception 'Project not found'; end if; end; $$;
create or replace function public.project_media_remove(p_id bigint, p_url text) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ begin if not public.is_admin() or p_id < 1 or p_url !~ ('^https?://[^/]+/storage/v1/object/public/portfolio-assets/projects/' || p_id::text || '/[^/]+$') then raise exception 'Invalid media request'; end if; update public.projects set images = coalesce(images,'[]'::jsonb) - p_url where id=p_id; if not found then raise exception 'Project not found'; end if; end; $$;
revoke all on function public.project_media_append(bigint,text), public.project_media_remove(bigint,text) from public;
grant execute on function public.project_media_append(bigint,text), public.project_media_remove(bigint,text) to authenticated;
create or replace function public.seed_portfolio_defaults(payload jsonb) returns void language plpgsql security definer set search_path = pg_catalog, public as $$
begin
  if not public.is_admin() then raise exception 'Not authorized'; end if;
  delete from public.projects; insert into public.projects select * from jsonb_populate_recordset(null::public.projects, payload->'projects');
  delete from public.skills; insert into public.skills select * from jsonb_populate_recordset(null::public.skills, payload->'skills');
  delete from public.experiences; insert into public.experiences select * from jsonb_populate_recordset(null::public.experiences, payload->'experiences');
  delete from public.education; insert into public.education select * from jsonb_populate_recordset(null::public.education, payload->'education');
  delete from public.profile; insert into public.profile select * from jsonb_populate_record(null::public.profile, payload->'profile');
  perform setval(pg_get_serial_sequence('public.projects','id'), coalesce((select max(id) from public.projects), 1), exists(select 1 from public.projects));
  perform setval(pg_get_serial_sequence('public.skills','id'), coalesce((select max(id) from public.skills), 1), exists(select 1 from public.skills));
  perform setval(pg_get_serial_sequence('public.experiences','id'), coalesce((select max(id) from public.experiences), 1), exists(select 1 from public.experiences));
  perform setval(pg_get_serial_sequence('public.education','id'), coalesce((select max(id) from public.education), 1), exists(select 1 from public.education));
end; $$;
revoke all on function public.seed_portfolio_defaults(jsonb) from public;
grant execute on function public.seed_portfolio_defaults(jsonb) to authenticated;
create or replace function public.submit_contact(p_name text, p_email text, p_message text, p_locale text) returns boolean language plpgsql security definer set search_path = pg_catalog, public as $$
begin
  p_name := btrim(p_name); p_email := lower(btrim(p_email)); p_message := btrim(p_message);
  if char_length(p_name) not between 1 and 120 or char_length(p_email) not between 3 and 254 or char_length(p_message) not between 1 and 5000 or p_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' or p_locale not in ('en','id') then raise exception 'Invalid contact input'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_email, 0));
  if exists (select 1 from public.contact_messages where email = p_email and created_at > now() - interval '1 minute') then return false; end if;
  insert into public.contact_messages(name,email,message,locale) values (p_name,p_email,p_message,p_locale); return true;
end; $$;
revoke all on function public.submit_contact(text,text,text,text) from public;
grant execute on function public.submit_contact(text,text,text,text) to anon, authenticated;
commit;
